'use client';

import * as React from 'react';
import * as DialogPrimitive from '@radix-ui/react-dialog';
import { cva, type VariantProps } from 'class-variance-authority';
import { XIcon } from './icons';
import { cn } from '@/lib/utils';

export const Dialog = DialogPrimitive.Root;
export const DialogTrigger = DialogPrimitive.Trigger;
export const DialogClose = DialogPrimitive.Close;

const Overlay = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    className={cn('fixed inset-0 z-50 bg-black/40 backdrop-blur-[2px] animate-in', className)}
    {...props}
  />
));
Overlay.displayName = 'DialogOverlay';

const CloseButton = () => (
  <DialogPrimitive.Close className="absolute right-3.5 top-3.5 grid size-7 place-items-center rounded-md text-muted-foreground outline-none transition-colors hover:bg-secondary hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/40">
    <XIcon className="size-4" />
    <span className="sr-only">Close</span>
  </DialogPrimitive.Close>
);

export const DialogContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content>
>(({ className, children, ...props }, ref) => (
  <DialogPrimitive.Portal>
    <Overlay />
    <DialogPrimitive.Content
      ref={ref}
      className={cn(
        'fixed left-1/2 top-1/2 z-50 grid w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 gap-4 rounded-xl border bg-popover p-6 shadow-xl outline-none animate-pop',
        className,
      )}
      {...props}
    >
      {children}
      <CloseButton />
    </DialogPrimitive.Content>
  </DialogPrimitive.Portal>
));
DialogContent.displayName = 'DialogContent';

const sheetVariants = cva(
  'fixed z-50 flex flex-col gap-4 bg-popover p-6 shadow-xl outline-none',
  {
    variants: {
      side: {
        right: 'inset-y-0 right-0 w-full max-w-md border-l animate-slide-right',
        left: 'inset-y-0 left-0 w-full max-w-md border-r animate-slide-left',
      },
    },
    defaultVariants: { side: 'right' },
  },
);

export const SheetContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> & VariantProps<typeof sheetVariants>
>(({ className, side, children, ...props }, ref) => (
  <DialogPrimitive.Portal>
    <Overlay />
    <DialogPrimitive.Content ref={ref} className={cn(sheetVariants({ side }), className)} {...props}>
      {children}
      <CloseButton />
    </DialogPrimitive.Content>
  </DialogPrimitive.Portal>
));
SheetContent.displayName = 'SheetContent';

export const DialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div className={cn('grid gap-1 pr-6', className)} {...props} />
);
export const DialogFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div className={cn('flex flex-col-reverse gap-2 sm:flex-row sm:justify-end', className)} {...props} />
);
export const DialogTitle = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Title ref={ref} className={cn('text-base font-semibold tracking-tight', className)} {...props} />
));
DialogTitle.displayName = 'DialogTitle';
export const DialogDescription = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description ref={ref} className={cn('text-[13px] text-muted-foreground', className)} {...props} />
));
DialogDescription.displayName = 'DialogDescription';

// A sheet is a dialog that docks to an edge.
export const Sheet = Dialog;
export const SheetTrigger = DialogTrigger;
export const SheetClose = DialogClose;
export const SheetHeader = DialogHeader;
export const SheetFooter = DialogFooter;
export const SheetTitle = DialogTitle;
export const SheetDescription = DialogDescription;

import 'dart:ui' as ui;

import 'package:flutter/material.dart';

import 'core.dart';
import 'icons.dart';
import 'theme.dart';

/// The panel of a dialog: a title, a line of help, your content and the buttons. Show it with [showBefDialog].
class BefDialog extends StatelessWidget {
  const BefDialog({
    super.key,
    this.title,
    this.description,
    this.child,
    this.actions = const [],
    this.onClose,
    this.maxWidth = 448,
  });
  final String? title;
  final String? description;
  final Widget? child;

  /// Buttons along the bottom, right-aligned.
  final List<Widget> actions;

  /// Shows the X in the corner when set.
  final VoidCallback? onClose;
  final double maxWidth;

  @override
  Widget build(BuildContext context) {
    final c = context.bef;
    return ConstrainedBox(
      constraints: BoxConstraints(maxWidth: maxWidth),
      child: Container(
        decoration: BoxDecoration(
          color: c.popover,
          borderRadius: BorderRadius.circular(BefRadius.xl),
          border: Border.all(color: c.border),
          boxShadow: const [
            BoxShadow(color: Color(0x40000000), blurRadius: 25, offset: Offset(0, 20), spreadRadius: -5),
          ],
        ),
        child: Stack(
          children: [
            Padding(
              padding: const EdgeInsets.all(24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  if (title != null || description != null)
                    Padding(
                      padding: const EdgeInsets.only(right: 24),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          if (title != null)
                            Text(
                              title!,
                              style: BefText.style(
                                context,
                                size: 16,
                                weight: FontWeight.w600,
                                color: c.popoverForeground,
                                letterSpacing: -0.2,
                              ),
                            ),
                          if (description != null) ...[
                            const SizedBox(height: 4),
                            Text(
                              description!,
                              style: BefText.style(context, size: 13, color: c.mutedForeground),
                            ),
                          ],
                        ],
                      ),
                    ),
                  if (child != null) ...[const SizedBox(height: 16), child!],
                  if (actions.isNotEmpty) ...[
                    const SizedBox(height: 16),
                    Wrap(alignment: WrapAlignment.end, spacing: 8, runSpacing: 8, children: actions),
                  ],
                ],
              ),
            ),
            if (onClose != null)
              Positioned(
                right: 14,
                top: 14,
                child: BefPressable(
                  semanticLabel: 'Close',
                  pressScale: 0.9,
                  onPressed: onClose,
                  builder: (context, states) => Container(
                    width: 28,
                    height: 28,
                    decoration: BoxDecoration(
                      color: states.contains(WidgetState.hovered) ? c.secondary : null,
                      borderRadius: BorderRadius.circular(BefRadius.md),
                    ),
                    alignment: Alignment.center,
                    child: BefIcon(BefIcons.x, size: 16, color: c.mutedForeground),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

/// Opens [builder] centred over a dimmed, slightly blurred page. Tap outside or press back to dismiss.
Future<T?> showBefDialog<T>({
  required BuildContext context,
  required WidgetBuilder builder,
  bool barrierDismissible = true,
}) {
  return showGeneralDialog<T>(
    context: context,
    barrierDismissible: barrierDismissible,
    barrierLabel: 'Dismiss',
    barrierColor: Colors.transparent,
    transitionDuration: const Duration(milliseconds: 200),
    pageBuilder: (context, _, _) => Stack(
      children: [
        Positioned.fill(
          child: BackdropFilter(
            filter: ui.ImageFilter.blur(sigmaX: 2, sigmaY: 2),
            child: const ColoredBox(color: Color(0x66000000)),
          ),
        ),
        SafeArea(
          child: Center(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Material(type: MaterialType.transparency, child: builder(context)),
            ),
          ),
        ),
      ],
    ),
    transitionBuilder: (context, anim, _, child) {
      final curved = CurvedAnimation(parent: anim, curve: Curves.easeOutCubic);
      return FadeTransition(
        opacity: curved,
        child: ScaleTransition(scale: Tween(begin: 0.97, end: 1.0).animate(curved), child: child),
      );
    },
  );
}

